import{_ as a,o as t,c as s,an as n}from"./chunks/framework.CYOK54rb.js";const p=JSON.parse('{"title":"What is GoMeta?","description":"","frontmatter":{"u_version":"0.1"},"headers":[],"relativePath":"concepts/what-is-gometa.md","filePath":"concepts/what-is-gometa.md"}'),o={name:"concepts/what-is-gometa.md"};function r(i,e,h,l,c,d){return t(),s("div",null,[...e[0]||(e[0]=[n('<h1 id="What-is-GoMeta?" tabindex="-1">What is <span class="gm-name">GoMeta</span>? <a class="header-anchor" href="#What-is-GoMeta?" aria-label="Permalink to &quot;What is GoMeta? {#What-is-GoMeta?}&quot;">​</a></h1><p><span class="gm-name">GoMeta.jl</span> is an <em>interpretable-metadata</em> engine, written in Julia, designed to work between, behind and within your data: in any programming language and any file format. In the words of <span class="gm-name">GoMeta</span>&#39;s author: &quot;The concept/idea of <span class="gm-name">GoMeta</span> is to embed its formalized metadata within all kinds of comments and enable Extensions to do something based on its output.&quot; His proposal for JuliaCon 2026 puts it this way: &quot;The core concept remains the same: Add interpretable meaning to comments within a Julia file by means of brief, simple, expressive and extendable metadata. The crux of the idea lies in its potential to serve a wider variety of different packages and even facilitating interactions between them.&quot; — &quot;However, in order to truly fulfill what had been promised, in particular to allow for the desired expressiveness and extensibility, language-like features had to be incorporated in the proposed schema.&quot; A file carries its ordinary content plus <code class="gm-ml"><span class="gm-sg">#~</span></code> <strong><a href="/reference/syntax-and-semantics#metaLine">metaLines</a></strong> — comment lines with machine-interpretable metadata (e.g. labels, visibility actions, conditions, etc.) sitting right beside the content they describe. <span class="gm-name">GoMeta</span> evaluates the metadata — more precisely, the <a href="/reference/syntax-and-semantics#the-GoMeta-Engine,-Extension"><span class="gm-name">GoMeta</span> Engine</a> evaluates it — but does not act on those evaluations: that is the <a href="/reference/syntax-and-semantics#the-GoMeta-Engine,-Extension">Extensions</a>&#39; role; they receive the evaluations through <span class="gm-name">GoMeta</span>&#39;s interface, <code>altValues_evals</code>.</p><p><span class="gm-name">GoMeta</span>&#39;s author explains <span class="gm-name">GoMeta</span> by asking and answering three questions. This page answers the first — what <span class="gm-name">GoMeta</span> is. <a href="./why-use-gometa">Why use <span class="gm-name">GoMeta</span>?</a> answers the second, and <a href="./how-does-gometa-work">How does <span class="gm-name">GoMeta</span> work?</a> the third.</p><h2 id="The-idea" tabindex="-1">The idea <a class="header-anchor" href="#The-idea" aria-label="Permalink to &quot;The idea {#The-idea}&quot;">​</a></h2><ol><li><p><strong>Embed</strong> formalized meaning — metadata — into comments: brief, simple, expressive and extendable metadata, riding where every language already has room for a comment.</p></li><li><p><strong>Absorb and evaluate.</strong> <span class="gm-name">GoMeta</span> absorbs that metadata — parses and interprets it — and evaluates which value of which <a href="/reference/syntax-and-semantics#Alterant">Alterant</a> applies to each piece of the file. Two main products come out of one run: the BLS Component tree — the file as <a href="/reference/syntax-and-semantics#BLS,-Component,-Block,-Line,-Segment,-File">BLS</a>, <span class="gm-name">GoMeta</span>&#39;s parser, recorded it — and the evaluated Alterant values, <code>altValues_evals</code>.</p></li><li><p><strong>Pass the evaluations on to the Extensions, which act on them.</strong> An Extension — a renderer, an Extension that produces a notebook or documentation, a program of your own — reads the two products through <span class="gm-name">GoMeta</span>&#39;s public surface and executes the task it was designed for. In the author&#39;s words, &quot;Extensions are called &#39;Extensions&#39; because they EXTEND THE CORE of <span class="gm-name">GoMeta</span>.&quot; The package ships a basic renderer as a development tool for looking at a run — strictly speaking no Extension, though it behaves like one: it lives under the package&#39;s development tools, and it is there because it serves a vital purpose for the package&#39;s development.</p></li></ol><h2 id="A-language-and-a-framework" tabindex="-1">A language and a framework <a class="header-anchor" href="#A-language-and-a-framework" aria-label="Permalink to &quot;A language and a framework {#A-language-and-a-framework}&quot;">​</a></h2><p>In the words of <span class="gm-name">GoMeta</span>&#39;s author: &quot;On the one hand, <span class="gm-name">GoMeta</span> is a domain specific language for metadata and on the other a framework with facilities on which Extensions can build.&quot; The language is the notation of the metaLines (e.g. statements, labels, conditions, the meta hierarchy, etc.) written in the comments of an ordinary file; the <a href="./../reference/syntax-and-semantics">Syntax &amp; semantics</a> page is its reference. The framework is the one run that reads a file and delivers the two main products, and the public surface through which the Extensions read them; <a href="./how-does-gometa-work">How does <span class="gm-name">GoMeta</span> work?</a> follows that run, and the <a href="./../reference/public-api">Public API</a> page names what a program calls.</p><h2 id="In-what-files" tabindex="-1">In what files <a class="header-anchor" href="#In-what-files" aria-label="Permalink to &quot;In what files {#In-what-files}&quot;">​</a></h2><p><span class="gm-name">GoMeta</span>&#39;s metadata lives in comments, so the file stays an ordinary file of its format and the host language never sees the metadata. At this release <span class="gm-name">GoMeta</span> reads three <a href="/reference/syntax-and-semantics#comment-marker">comment markers</a>: Julia&#39;s <code>#</code>, the C family&#39;s <code>//</code> (e.g. C, Rust, etc.), and LaTeX&#39;s <code>%</code> — the marker is named when <span class="gm-name">GoMeta</span> is called (Julia is the default), never inferred from the file. The author intends <span class="gm-name">GoMeta</span> for all kinds of comments: his talk lists Julia and Python, C and Rust, and LaTeX as implemented, Word documents (the <code>.fodt</code> format to start with), and, not yet, spreadsheets and metadata attached to images, video and the like. That reach is the reason for the name — <span class="gm-name">GoMeta</span> works in between them, behind them, within them — stated in the author&#39;s words on the <a href="./../">front page</a>.</p><h2 id="Status" tabindex="-1">Status <a class="header-anchor" href="#Status" aria-label="Permalink to &quot;Status {#Status}&quot;">​</a></h2><p><span class="gm-name">GoMeta</span> was presented and released at JuliaCon 2026; in the author&#39;s words, the package &quot;finally implements a vastly matured offspring of a [my] half-baked idea proposed at JuliaCon2025.&quot; <span class="gm-name">GoMeta.jl</span> <code>0.4.0</code> is <strong>alpha</strong>: a working, tested engine for the <strong>v0 subset</strong> of the <span class="gm-name">GoMeta</span> language. The seven committed example pairs render byte for byte under the shipped test suite, and input the grammar does not accept meets a stable refusal: <span class="gm-name">GoMeta</span> stops with a message that says what it could not accept, and nothing is delivered. The surface may still move — until at least version 0.7 every change of the public surface is a clean cut (no leftover of an older version in a newer one), the author&#39;s policy, and the package&#39;s own documents keep the register of every such change. The language grows by design; the v0 subset forecloses none of it.</p><p><span class="gm-name">GoMeta</span> is <strong>Fair Source</strong> — licensed under the Functional Source License, Version 1.1, MIT Future License (<strong>FSL-1.1-MIT</strong>; source-available, not OSI-approved open source): free for everyone&#39;s own use — at work, at university, in the public sector — including internal use and access, non-commercial education and research, and professional services provided to other licensees. Not licensed: offering <span class="gm-name">GoMeta</span> to others in a commercial product or service that competes with it or with the Licensor&#39;s own <span class="gm-name">GoMeta</span>-based offerings (for that, contact hello@gometa.dev). Each release automatically becomes <strong>MIT-licensed</strong> on its second anniversary. See the <a href="https://github.com/gometa-jl/GoMeta.jl" target="_blank" rel="noreferrer">repository</a> for the LICENSE file and details.</p><p>From here: <a href="./why-use-gometa">Why use <span class="gm-name">GoMeta</span>?</a> — what it is for; <a href="./how-does-gometa-work">How does <span class="gm-name">GoMeta</span> work?</a> — one run, from a file to what the Extensions receive; <a href="./../tutorials/getting-started">Getting started</a> — the install and one complete run.</p>',13)])])}const u=a(o,[["render",r]]);export{p as __pageData,u as default};
